from datetime import datetime
from rest_framework_jwt.settings import api_settings
from rest_framework_jwt.views import ObtainJSONWebToken
from .models import StaffFacilityAssignment

def custom_facility_jwt_payload(user, request=None):
    payload = {
        'user_id': user.id,
        'username': user.username,
        'exp': datetime.utcnow() + api_settings.JWT_EXPIRATION_DELTA
    }
    if request and request.data:
        facility_id = request.data.get('facility_id')
        if facility_id:
            # Query verified staff assignment for authenticating user
            assignment = StaffFacilityAssignment.objects.filter(user=user, facility_id=facility_id, is_active=True).first()
            if assignment:
                payload['facility_id'] = facility_id
                payload['facility_role'] = assignment.assigned_role
            else:
                payload['facility_id'] = None
                payload['facility_role'] = 'guest'
    return payload

class HospitalAuthView(ObtainJSONWebToken):
    pass
